  const tv = trendVal(p.trend);                                            // trend: up rescues, down dampens (never kills)
  const trend = 1 + Math.max(-0.15, Math.min(0.18, tv/200));
  const mixd = (p.heat_mix!=null && p.heat!=null) ? (p.heat_mix - p.heat) : 0;  // good pitch mix
  const mix = 1 + Math.max(-0.10, Math.min(0.15, mixd/100));
