  const tier = R.days ? Math.max(0.8, Math.min(1.3, (R.tiers[tierOf(p.heat)] ?? R.base)/R.base)) : 1;  // tracker
  const park = (p.park_hr && p.park_hr.boost!=null) ? (1 + p.park_hr.boost/300) : 1;
